"use client";

import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Kbd } from "@/components/ui/kbd";

import { BlockFrame } from "../parts/block-frame";
import {
  INITIAL_DELIVERIES,
  TEST_ENDPOINT,
  type TestDelivery,
  type TestResponse,
  clockAfter,
  requestHeaders,
  samplePayload,
  simulateResponse,
} from "./webhook-tester/data";
import { EventPicker } from "./webhook-tester/event-picker";
import { JsonEditor, byteLength, checkJson } from "./webhook-tester/json-editor";
import { RecentDeliveries } from "./webhook-tester/recent-deliveries";
import { ResponsePanel } from "./webhook-tester/response-panel";
import { SecretField } from "./webhook-tester/secret-field";
import { type SendStage, SendTimeline } from "./webhook-tester/send-timeline";
import type { WebhookEvent } from "./webhooks/data";
import { LoaderIcon, SendIcon } from "./icons";

/**
 * A test bench for one webhook endpoint: pick an event, edit its JSON body,
 * and send it signed. A timeline follows the post from signing to the answer,
 * the answer opens in tabs, and recent posts list with Retry on a failure.
 */
export function WebhookTester({ className }: { className?: string }) {
  const [endpoint, setEndpoint] = useState(TEST_ENDPOINT);
  const [event, setEvent] = useState<WebhookEvent>("booking.created");
  const [payload, setPayload] = useState(() => samplePayload("booking.created"));
  const [stage, setStage] = useState<SendStage>("idle");
  const [response, setResponse] = useState<TestResponse | null>(null);
  const [deliveries, setDeliveries] = useState<TestDelivery[]>(INITIAL_DELIVERIES);
  const [announcement, setAnnouncement] = useState("");
  const attempts = useRef(0);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const titleId = useId();
  const endpointId = useId();
  const eventId = useId();
  const secretId = useId();

  useEffect(() => () => timers.current.forEach(clearTimeout), []);

  const busy = stage !== "idle" && stage !== "done";
  const valid = checkJson(payload).valid;
  const later = (ms: number, run: () => void) => timers.current.push(setTimeout(run, ms));

  const send = (sentEvent: WebhookEvent = event, body: string = payload) => {
    if (busy) return;
    if (!checkJson(body).valid) {
      setAnnouncement("Fix the JSON before sending.");
      return;
    }
    timers.current.forEach(clearTimeout);
    timers.current = [];
    attempts.current += 1;
    const answer = simulateResponse(sentEvent, attempts.current);
    const count = attempts.current;
    setResponse(null);
    setStage("signing");
    setAnnouncement(`Sending ${sentEvent}.`);
    later(350, () => setStage("sending"));
    later(750, () => setStage("waiting"));
    later(750 + answer.durationMs + 450, () => {
      setStage("done");
      setResponse(answer);
      setDeliveries((current) => [{ id: `n${count}`, event: sentEvent, status: answer.status, time: clockAfter(count), durationMs: answer.durationMs }, ...current].slice(0, 8));
      setAnnouncement(answer.status < 400 ? `Delivered. The endpoint answered ${answer.status} in ${answer.durationMs} ms.` : `Failed. The endpoint answered ${answer.status}.`);
    });
  };

  const sendOnShortcut = (keyEvent: KeyboardEvent<HTMLElement>) => {
    if (keyEvent.key === "Enter" && (keyEvent.metaKey || keyEvent.ctrlKey)) {
      keyEvent.preventDefault();
      send();
    }
  };

  const pickEvent = (next: WebhookEvent) => {
    setEvent(next);
    setPayload(samplePayload(next));
  };

  const retry = (item: TestDelivery) => {
    const body = samplePayload(item.event);
    setEvent(item.event);
    setPayload(body);
    send(item.event, body);
  };

  const request = `POST ${endpoint}\n${requestHeaders(event, byteLength(payload))
    .map(([name, value]) => `${name}: ${value}`)
    .join("\n")}\n\n${payload}`;
  const label = "text-xs font-medium text-muted-foreground";

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-8 gap-y-4 border-b border-border px-5 py-4">
        <div className="min-w-0 max-w-sm">
          <h2 id={titleId} className="text-base font-semibold">
            Test a webhook
          </h2>
          <p className="text-sm text-muted-foreground">Send a signed sample event to your endpoint and check that it answers 2xx.</p>
        </div>
        <div className="w-full @2xl:w-96">
          <SendTimeline stage={stage} status={response?.status ?? null} durationMs={response?.durationMs ?? null} />
        </div>
      </header>

      <div className="flex flex-col gap-4 p-5">
        <div className="grid gap-4 @3xl:grid-cols-[minmax(0,2fr)_auto_minmax(0,1fr)]">
          <div className="flex min-w-0 flex-col gap-1.5">
            <label htmlFor={endpointId} className={label}>
              Endpoint
            </label>
            <div className="flex min-w-0 items-center gap-2 font-mono">
              <span className="rounded-sm bg-marketing-blue-surface px-1.5 py-0.5 text-xs font-medium text-marketing-blue-ink">POST</span>
              <Input
                id={endpointId}
                value={endpoint}
                inputMode="url"
                autoComplete="off"
                spellCheck={false}
                onChange={(change) => setEndpoint(change.target.value)}
                onKeyDown={sendOnShortcut}
                className="flex-1"
              />
            </div>
          </div>
          <div className="flex flex-col gap-1.5">
            <span id={eventId} className={label}>
              Event
            </span>
            <EventPicker value={event} onChange={pickEvent} labelId={eventId} />
          </div>
          <div className="flex min-w-0 flex-col gap-1.5">
            <span id={secretId} className={label}>
              Signing secret
            </span>
            <div className="flex h-9 min-w-0 items-center rounded-md border border-border pl-3">
              <SecretField labelId={secretId} />
            </div>
          </div>
        </div>

        <JsonEditor value={payload} onChange={setPayload} onSubmit={() => send()} />

        <div className="flex flex-wrap items-center justify-between gap-3">
          <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
            <Kbd>Ctrl</Kbd>
            <Kbd>Enter</Kbd>
            <span>to send, or Cmd on a Mac</span>
          </p>
          <Button type="button" disabled={busy || !valid} aria-busy={busy} onClick={() => send()}>
            {busy ? <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" /> : <SendIcon aria-hidden="true" className="size-4" />}
            Send test event
          </Button>
        </div>
      </div>

      <div className="flex flex-col gap-6 border-t border-border p-5">
        <ResponsePanel body={response?.body ?? null} headers={response?.headers ?? []} request={request} />
        <RecentDeliveries deliveries={deliveries} onRetry={retry} busy={busy} />
      </div>
      <p role="status" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import type { WebhookEvent } from "../webhooks/data";

/** Where the test bench posts, a made-up clinic host. */
export const TEST_ENDPOINT = "https://desk.harbour-clinic.example/hooks/fernhill";

/** The sample signing secret. It is fake and only ever shown masked or as this sample. */
export const TEST_SECRET = "whsec_test_8c1e5b7d0a2f94e63f9a";

/** The secret as the field shows it before Show is pressed. */
export const MASKED_SECRET = "whsec_test_••••••••••••3f9a";

/** A sample body for each event, written as an editor would hold it. */
export function samplePayload(event: WebhookEvent): string {
  const base = {
    id: "evt_test_7Hq2mKd91",
    type: event,
    created: 1793111528,
    livemode: false,
  };
  const data =
    event === "patient.updated"
      ? { patient_id: "pt_test_4410", changed: ["phone", "preferred_clinic"], clinic: "Mill Lane" }
      : event === "visit.checked_in"
        ? { visit_id: "vs_test_2201", room: "Room 3", practitioner: "Dr Lena Moss", waited_minutes: 6 }
        : { booking_id: "bk_test_9032", clinic: "Harbour Street", practitioner: "Dr Lena Moss", starts_at: "2026-11-02T09:30:00Z", status: event === "booking.cancelled" ? "cancelled" : "confirmed" };
  return JSON.stringify({ ...base, data }, null, 2);
}

/** One test post in the recent list. */
export interface TestDelivery {
  id: string;
  event: WebhookEvent;
  status: number;
  time: string;
  durationMs: number;
}

/** The posts already in the list when the bench opens. */
export const INITIAL_DELIVERIES: TestDelivery[] = [
  { id: "t4", event: "booking.created", status: 200, time: "14:32:09", durationMs: 184 },
  { id: "t3", event: "patient.updated", status: 500, time: "14:11:42", durationMs: 412 },
  { id: "t2", event: "visit.checked_in", status: 200, time: "13:57:19", durationMs: 96 },
];

/** What the simulated endpoint answers. */
export interface TestResponse {
  status: number;
  durationMs: number;
  body: string;
  headers: [string, string][];
}

/**
 * The endpoint's answer to a post. Every other `patient.updated` post fails
 * with a 500, so the bench shows a failure and a retry.
 */
export function simulateResponse(event: WebhookEvent, attempt: number): TestResponse {
  const fails = event === "patient.updated" && attempt % 2 === 1;
  const durationMs = fails ? 412 : 120 + ((attempt * 37) % 90);
  return {
    status: fails ? 500 : 200,
    durationMs,
    body: fails ? JSON.stringify({ error: "patient sync is busy, try again" }, null, 2) : JSON.stringify({ received: true }, null, 2),
    headers: [
      ["Content-Type", "application/json"],
      ["Date", "Sat, 31 Oct 2026 14:40:00 GMT"],
      ["X-Request-Id", `req_test_${(4096 + attempt * 311).toString(16)}`],
    ],
  };
}

/** The headers Fernhill sends with a test post. */
export function requestHeaders(event: WebhookEvent, bytes: number): [string, string][] {
  return [
    ["Content-Type", "application/json"],
    ["Content-Length", String(bytes)],
    ["Fernhill-Event", event],
    ["Fernhill-Signature", "t=1793111528,v1=5d0e••••••••3f9a"],
  ];
}

/** A clock time a few seconds after the last post, so new rows read in order. */
export const clockAfter = (count: number) => {
  const seconds = 14 * 3600 + 40 * 60 + count * 7;
  const part = (value: number) => String(value).padStart(2, "0");
  return `${part(Math.floor(seconds / 3600))}:${part(Math.floor(seconds / 60) % 60)}:${part(seconds % 60)}`;
};

import { seededRandom } from "../../lib/plot";

/** The events Fernhill can post to an endpoint. */
export const WEBHOOK_EVENTS = ["booking.created", "booking.cancelled", "visit.checked_in", "patient.updated"] as const;

/** One event name Fernhill posts. */
export type WebhookEvent = (typeof WEBHOOK_EVENTS)[number];

/** One hour of posts to an endpoint. */
export interface HourBucket {
  ok: number;
  failed: number;
}

/** One post to an endpoint, kept in the delivery history. */
export interface Delivery {
  id: string;
  event: WebhookEvent;
  /** The HTTP status the endpoint answered with. 0 means it timed out. */
  status: number;
  /** Clock time of the post, such as "14:32". */
  time: string;
  durationMs: number;
  /** The hour bucket the post counts in, so a retry can move it from failed to ok. */
  hour: number;
  /** How many times Fernhill has tried this post. */
  attempts: number;
}

/** One endpoint that receives Fernhill events. */
export interface Endpoint {
  id: string;
  name: string;
  url: string;
  addedBy: string;
  addedOn: string;
  /** Always a masked sample, never a real secret. */
  secret: string;
  apiVersion: string;
  hours: HourBucket[];
  deliveries: Delivery[];
}

/** How many hourly bars the chart shows. */
export const HOURS = 24;

/** The clock label of an hour bucket today, from 00:00 to 23:00. */
export const hourLabel = (hour: number) => `${String(hour).padStart(2, "0")}:00`;

function makeHours(seed: number, base: number, failures: number[]): HourBucket[] {
  const random = seededRandom(seed);
  return Array.from({ length: HOURS }, (_, hour) => {
    // Clinics book in the working day, so posts rise from 7:00 and fall after 19:00.
    const day = hour >= 7 && hour <= 19 ? 1 : 0.25;
    const ok = Math.round(base * day * (0.7 + random() * 0.6));
    return { ok, failed: failures.includes(hour) ? 1 + Math.floor(random() * 2) : 0 };
  });
}

function delivery(id: string, event: WebhookEvent, status: number, hour: number, minute: number, durationMs: number): Delivery {
  return { id, event, status, time: `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")}`, durationMs, hour, attempts: status >= 200 && status < 300 ? 1 : 3 };
}

