/** Whether a status code counts as delivered. */
export const isDelivered = (status: number) => status >= 200 && status < 300;

/** The share of posts in the last 24 hours that were delivered, from 0 to 100. */
export function deliveryRate(endpoint: Endpoint): number {
  const ok = endpoint.hours.reduce((sum, hour) => sum + hour.ok, 0);
  const failed = endpoint.hours.reduce((sum, hour) => sum + hour.failed, 0);
  return ok + failed === 0 ? 100 : (ok / (ok + failed)) * 100;
}

/** How many deliveries in the history still failed. */
export const failingCount = (endpoint: Endpoint) => endpoint.deliveries.filter((item) => !isDelivered(item.status)).length;

/** The body Fernhill posted for one delivery, as the inspector shows it. */
export function samplePayload(endpoint: Endpoint, item: Delivery) {
  return {
    id: `evt_test_${item.id}${endpoint.id.slice(0, 3)}`,
    type: item.event,
    created: `2026-10-31T${item.time}:00Z`,
    api_version: endpoint.apiVersion,
    data: {
      booking_id: `bk_test_${item.id}4821`,
      clinic: "Harbour Street",
      practitioner: "Dr Lena Moss",
      room: "Room 3",
      starts_at: "2026-11-02T09:30:00Z",
    },
  };
}

/** The headers Fernhill sent with one delivery. */
export function sampleHeaders(endpoint: Endpoint, item: Delivery): [string, string][] {
  return [
    ["Content-Type", "application/json"],
    ["User-Agent", "Fernhill-Webhooks/2.4"],
    ["Fernhill-Event", item.event],
    ["Fernhill-Attempt", String(item.attempts)],
    ["Fernhill-Signature", `t=1793111528,v1=${endpoint.secret.slice(-4)}••••••••`],
  ];
}

/** The status text the history shows for a code. */
export const statusLabel = (status: number) => (status === 0 ? "Timed out" : String(status));

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { ChevronDownIcon, CheckIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { WEBHOOK_EVENTS, type WebhookEvent } from "../webhooks/data";

/** Props for the event picker. */
export interface EventPickerProps {
  value: WebhookEvent;
  onChange: (event: WebhookEvent) => void;
  /** The id of the visible label that names the picker. */
  labelId: string;
}

/**
 * Picks the sample event to send. A button opens a listbox: arrows, Home and
 * End move, Enter or Space picks, Escape or a click outside closes and returns
 * focus to the button.
 */
export function EventPicker({ value, onChange, labelId }: EventPickerProps) {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(() => WEBHOOK_EVENTS.indexOf(value));
  const buttonRef = useRef<HTMLButtonElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const wrapRef = useRef<HTMLDivElement>(null);
  const listId = useId();
  const optionId = (index: number) => `${listId}-${index}`;

  useEffect(() => {
    if (!open) return;
    listRef.current?.focus();
    const onPointer = (event: PointerEvent) => {
      if (event.target instanceof Node && !wrapRef.current?.contains(event.target)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointer);
    return () => document.removeEventListener("pointerdown", onPointer);
  }, [open]);

  const close = () => {
    setOpen(false);
    buttonRef.current?.focus();
  };

  const pick = (index: number) => {
    const event = WEBHOOK_EVENTS[index];
    if (event) onChange(event);
    close();
  };

  const onListKey = (event: KeyboardEvent) => {
    const last = WEBHOOK_EVENTS.length - 1;
    let next = active;
    if (event.key === "ArrowDown") next = Math.min(last, active + 1);
    else if (event.key === "ArrowUp") next = Math.max(0, active - 1);
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = last;
    else if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      pick(active);
      return;
    } else if (event.key === "Escape" || event.key === "Tab") {
      if (event.key === "Escape") event.preventDefault();
      close();
      return;
    } else return;
    event.preventDefault();
    setActive(next);
  };

  return (
    <div ref={wrapRef} className="relative">
      <Button
        ref={buttonRef}
        type="button"
        variant="outline"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listId : undefined}
        aria-labelledby={`${labelId} ${listId}-value`}
        onClick={() => {
          setActive(WEBHOOK_EVENTS.indexOf(value));
          setOpen(!open);
        }}
        onKeyDown={(event) => {
          if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
          event.preventDefault();
          setActive(WEBHOOK_EVENTS.indexOf(value));
          setOpen(true);
        }}
      >
        <span id={`${listId}-value`} className="font-mono text-xs">
          {value}
        </span>
