/** Props for the payload editor. */
export interface JsonEditorProps {
  value: string;
  onChange: (value: string) => void;
  /** Called on Mod+Enter, so a person can send without leaving the editor. */
  onSubmit: () => void;
}

/** Whether a text parses as JSON, and the parse error when it does not. */
export function checkJson(text: string): { valid: true } | { valid: false; message: string } {
  try {
    JSON.parse(text);
    return { valid: true };
  } catch (error) {
    return { valid: false, message: error instanceof Error ? error.message : "Not valid JSON" };
  }
}

/** The size of a text in bytes once it is UTF-8 encoded, as it goes over the wire. */
export const byteLength = (text: string) => new TextEncoder().encode(text).length;

/**
 * A JSON editor with line numbers. Enter keeps the line's indent and indents
 * one step after an opening brace or bracket. Under it, a line says whether
 * the JSON is valid and how many bytes it is, with a Format button.
 */
export function JsonEditor({ value, onChange, onSubmit }: JsonEditorProps) {
  const area = useRef<HTMLTextAreaElement>(null);
  const gutter = useRef<HTMLDivElement>(null);
  const statusId = useId();
  const lines = value.split("\n").length;
  const check = checkJson(value);

  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
      event.preventDefault();
      onSubmit();
      return;
    }
    if (event.key !== "Enter" || event.shiftKey || event.altKey) return;
    const element = event.currentTarget;
    const { selectionStart: start, selectionEnd: end } = element;
    const lineStart = value.lastIndexOf("\n", start - 1) + 1;
    const indent = /^[ \t]*/.exec(value.slice(lineStart, start))?.[0] ?? "";
    const before = value.slice(lineStart, start).trimEnd().slice(-1);
    const opens = before === "{" || before === "[";
    const inner = opens ? `${indent}  ` : indent;
    // Between a pair such as {}, the closing mark drops to its own line at the outer indent.
    const closing = opens && /^[ \t]*[}\]]/.test(value.slice(end)) ? `\n${indent}` : "";
    event.preventDefault();
    const insert = `\n${inner}`;
    onChange(value.slice(0, start) + insert + closing + value.slice(end));
    const caret = start + insert.length;
    requestAnimationFrame(() => area.current?.setSelectionRange(caret, caret));
  };

  return (
    <div className="flex min-w-0 flex-col gap-1">
      <div className="flex h-64 min-w-0 gap-1 font-mono">
        {/* The transparent border and padding match the field's, so each number sits level with its line. */}
        <div
          ref={gutter}
          aria-hidden="true"
          className="w-9 shrink-0 overflow-hidden border-y border-transparent py-2 pr-1 text-right text-base text-muted-foreground select-none md:text-sm"
        >
          {Array.from({ length: lines }, (_, index) => (
            <div key={index}>{index + 1}</div>
          ))}
        </div>
        <Textarea
          ref={area}
          value={value}
          spellCheck={false}
          aria-label="Payload, JSON"
          aria-describedby={statusId}
          aria-invalid={!check.valid}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={onKeyDown}
          onScroll={(event) => {
            if (gutter.current) gutter.current.scrollTop = event.currentTarget.scrollTop;
          }}
          className="h-full flex-1 resize-none whitespace-pre"
        />
      </div>
      <div className="flex min-h-10 items-center justify-between gap-3 py-1.5 pl-10 text-xs">
        <p id={statusId} className={cn("flex min-w-0 items-center gap-1.5", check.valid ? STATUS_TEXT.good : STATUS_TEXT.bad)}>
          {check.valid ? <CircleCheckIcon aria-hidden="true" className="size-4 shrink-0" /> : <CircleXIcon aria-hidden="true" className="size-4 shrink-0" />}
          <span className="truncate">{check.valid ? `Valid JSON, ${byteLength(value)} bytes` : `Invalid JSON: ${check.message}`}</span>
        </p>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={!check.valid}
          onClick={() => onChange(JSON.stringify(JSON.parse(value), null, 2))}
        >
          Format
        </Button>
      </div>
    </div>
  );
}

