/** Where a test post is: not sent, being signed, on its way, waiting for an answer, or answered. */
export type SendStage = "idle" | "signing" | "sending" | "waiting" | "done";

/** Props for the three-step timeline of a test post. */
export interface SendTimelineProps {
  stage: SendStage;
  /** The answer's status and time, once there is one. */
  status: number | null;
  durationMs: number | null;
}

const ORDER: SendStage[] = ["idle", "signing", "sending", "waiting", "done"];

/**
 * Three steps of a test post: signed, sent and the response. Each step's icon
 * crossfades as it completes, the line between steps fills left to right, and
 * a dot travels the last line while the endpoint has not answered.
 */
export function SendTimeline({ stage, status, durationMs }: SendTimelineProps) {
  const at = ORDER.indexOf(stage);
  const ok = status !== null && status >= 200 && status < 300;
  const icon = (done: boolean, Icon: ComponentType<SVGProps<SVGSVGElement>>) => (done ? <CircleCheckIcon aria-hidden="true" className="size-4" /> : <Icon aria-hidden="true" className="size-3.5" />);

  return (
    <ol aria-label="Test post progress" className="flex items-start gap-2">
      <li className="flex w-20 shrink-0 flex-col gap-1">
        <StageIcon state={at >= 2 ? "good" : at === 1 ? "active" : "waiting"}>{icon(at >= 2, SignatureIcon)}</StageIcon>
        <span className="text-xs font-medium">Signed</span>
        <span className="text-xs text-muted-foreground">HMAC SHA-256</span>
      </li>
      <Connector filled={at >= 2} travelling={false} />
      <li className="flex w-20 shrink-0 flex-col gap-1">
        <StageIcon state={at >= 3 ? "good" : at === 2 ? "active" : "waiting"}>{icon(at >= 3, SendIcon)}</StageIcon>
        <span className="text-xs font-medium">Sent</span>
        <span className="text-xs text-muted-foreground">POST</span>
      </li>
      <Connector filled={at >= 4} travelling={stage === "waiting"} />
      <li className="flex w-20 shrink-0 flex-col gap-1">
        <StageIcon state={stage === "done" ? (ok ? "good" : "bad") : stage === "waiting" ? "active" : "waiting"}>
          {stage === "done" && !ok ? <CircleXIcon aria-hidden="true" className="size-4" /> : icon(stage === "done", CircleCheckIcon)}
        </StageIcon>
        <span className="text-xs font-medium tabular-nums">{stage === "done" && status !== null ? `${status} ${ok ? "OK" : "Error"}` : "Response"}</span>
        <span className="text-xs text-muted-foreground tabular-nums">{stage === "done" && durationMs !== null ? `${durationMs} ms` : stage === "waiting" ? "Waiting" : "Not sent"}</span>
      </li>
    </ol>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";

/** The round mark of one step of a test post. Its glyph crossfades with a small scale when the state changes. */
export function StageIcon({ state, children }: { state: "waiting" | "active" | "good" | "bad"; children: ReactNode }) {
  const reduceMotion = useReducedMotion();
  return (
    <span
      className={cn(
        "relative flex size-6 shrink-0 items-center justify-center rounded-full border",
        state === "waiting" ? "border-border text-muted-foreground" : state === "bad" ? cn("border-current", STATUS_TEXT.bad) : state === "good" ? cn("border-current", STATUS_TEXT.good) : "border-chart-1 text-chart-1",
      )}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={state}
          initial={reduceMotion ? false : { opacity: 0, scale: 0.6 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, scale: 0.6 }}
          transition={{ duration: 0.18 }}
          className="flex"
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

/**
 * The line between two steps of a test post. It fills left to right when the
 * later step starts, and a dot travels along it while a step is in flight.
 */
export function Connector({ filled, travelling }: { filled: boolean; travelling: boolean }) {
  const reduceMotion = useReducedMotion();
  return (
    <span aria-hidden="true" className="relative mt-3 h-0.5 flex-1 overflow-hidden rounded-full bg-border">
      <span className={cn("absolute inset-0 origin-left rounded-full bg-chart-1 motion-safe:transition-transform motion-safe:duration-300", filled ? "scale-x-100" : "scale-x-0")} />
      {travelling && !reduceMotion ? (
        <motion.span
          className="absolute top-1/2 size-1.5 -translate-y-1/2 rounded-full bg-chart-1"
          initial={{ left: "0%" }}
          animate={{ left: ["0%", "100%"] }}
          transition={{ duration: 0.7, ease: "easeInOut", repeat: Infinity }}
        />
      ) : null}
    </span>
  );
}
